mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>WellSource — Trusted Health & Wellness</title>
  <meta name="description" content="WellSource is your trusted source for medically reviewed health and wellness guidance." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Cabinet+Grotesk:wght@500;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #f7fbfa;
      --surface: #ffffff;
      --surface-soft: #eef6f4;
      --text: #143532;
      --muted: #5a7470;
      --primary: #1f8a7b;
      --primary-dark: #176a60;
      --accent: #f39a6b;
      --accent-strong: #e78450;
      --line: #dcebe7;
      --shadow: 0 14px 30px rgba(20, 53, 50, 0.08);
      --radius: 18px;
      --radius-sm: 12px;
      --container: 1180px;
    }
    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: "Plus Jakarta Sans", sans-serif;
      color: var(--text);
      background: linear-gradient(180deg, #f7fbfa 0%, #f9f7f5 100%);
      line-height: 1.55;
    }
    .container { width: min(var(--container), calc(100% - 2.25rem)); margin: 0 auto; }
    .pill { border: 1px solid var(--line); border-radius: 999px; padding: .35rem .75rem; font-size: .8rem; color: var(--muted); background: #fff; }
    h1,h2,h3,h4 { font-family: "Cabinet Grotesk", sans-serif; margin: 0; line-height: 1.1; letter-spacing: -.01em; }
    h1 { font-size: clamp(2.1rem, 5vw, 4rem); }
    h2 { font-size: clamp(1.6rem, 3.4vw, 2.6rem); }
    h3 { font-size: clamp(1.1rem, 2vw, 1.4rem); }
    p { margin: 0; color: var(--muted); }

    .topbar {
      border-bottom: 1px solid var(--line);
      background: rgba(255,255,255,.85);
      backdrop-filter: blur(8px);
      position: sticky;
      top: 0;
      z-index: 30;
    }
    .topbar-wrap { display:flex; align-items:center; justify-content:space-between; gap: 1rem; min-height: 72px; }
    .brand { display:flex; align-items:center; gap:.7rem; font-family:"Cabinet Grotesk"; font-size:1.6rem; font-weight:800; color:var(--primary-dark); text-decoration:none; }
    .brand-dot { width: 12px; height: 12px; border-radius: 50%; background: radial-gradient(circle at 30% 30%, #9ee1ce, var(--primary)); box-shadow: 0 0 0 7px #e5f5f0; }

    .main-nav { position: relative; }
    .menu { list-style:none; display:flex; gap:.35rem; margin:0; padding:0; flex-wrap: wrap; }
    .menu-btn {
      border: 0; background: transparent; padding: .6rem .85rem; border-radius: 10px;
      font: inherit; color: var(--text); cursor:pointer; font-weight:600;
    }
    .menu-btn:hover, .menu-btn.active { background: #e9f4f2; color: var(--primary-dark); }

    .mega {
      position:absolute; top: calc(100% + .65rem); left: 0; right: 0;
      background: var(--surface); border:1px solid var(--line); border-radius: var(--radius);
      box-shadow: var(--shadow); padding: 1rem; display:none;
      grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .85rem;
    }
    .mega.open { display:grid; }
    .mega-col { background:#f8fcfb; border:1px solid var(--line); border-radius: var(--radius-sm); padding:.85rem; }
    .mega-col h4 { font-size: .95rem; margin-bottom:.5rem; }
    .mega-col a { display:block; color:var(--muted); text-decoration:none; font-size:.88rem; padding:.26rem 0; }
    .mega-col a:hover { color:var(--primary-dark); }

    .ticker {
      margin-top: .6rem; border-top:1px solid var(--line); border-bottom:1px solid var(--line);
      background: #f1f9f6; overflow:hidden;
    }
    .ticker-track {
      display:flex; gap:1.5rem; width:max-content; padding:.62rem 0; align-items:center;
      animation: ticker 24s linear infinite;
    }
    .ticker:hover .ticker-track { animation-play-state: paused; }
    .stat { display:flex; align-items:center; gap:.55rem; white-space:nowrap; font-weight:600; color:#215650; }
    .stat b { color: var(--primary-dark); }
    .dot { width:7px; height:7px; border-radius:50%; background:var(--accent); }
    @keyframes ticker { from { transform: translateX(0);} to { transform: translateX(-50%);} }

    .hero { padding: 2rem 0 1.5rem; }
    .hero-grid { display:grid; grid-template-columns: 1.3fr .8fr; gap: 1rem; }
    .card { background: var(--surface); border:1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); }
    .hero-main { padding: 1.3rem; }
    .meta { display:flex; gap:.5rem; flex-wrap:wrap; margin-bottom:.9rem; }
    .hero-main p { margin: .9rem 0 1.2rem; max-width: 66ch; }
    .cta { display:inline-flex; align-items:center; gap:.5rem; border:0; background:var(--accent); color:#fff; font-weight:700; padding:.78rem 1.05rem; border-radius: 12px; cursor:pointer; }
    .cta:hover { background:var(--accent-strong); }

    .trending { padding:1rem; }
    .trending h3 { margin-bottom:.8rem; }
    .trend-item { padding:.7rem 0; border-top:1px dashed var(--line); }
    .trend-item:first-of-type { border-top:0; }
    .trend-cat { font-size:.75rem; color:var(--primary); font-weight:700; text-transform:uppercase; letter-spacing:.04em; }
    .trend-item a { display:block; margin-top:.24rem; color:var(--text); text-decoration:none; font-weight:600; }
    .trend-item a:hover { color:var(--primary-dark); }

    .section { padding: 1.35rem 0; }
    .section-head { display:flex; align-items:end; justify-content:space-between; margin-bottom:.9rem; gap:.8rem; }

    .carousel-wrap { position:relative; }
    .carousel { display:flex; gap:.8rem; overflow:hidden; scroll-behavior:smooth; padding: .2rem; }
    .topic { min-width: 170px; text-align:center; background:var(--surface); border:1px solid var(--line); border-radius:16px; padding:.9rem .6rem; }
    .topic-img {
      width:88px; height:88px; border-radius:50%; margin:0 auto .62rem;
      background: radial-gradient(circle at 30% 20%, #d7f0ea, #9bcfc2);
      border: 4px solid #ecf8f5;
    }
    .topic span { font-weight:700; font-size:.92rem; color:#234a45; }
    .arrow { position:absolute; top:45%; transform:translateY(-50%); width:38px; height:38px; border-radius:50%; border:1px solid var(--line); background:#fff; cursor:pointer; box-shadow: var(--shadow); }
    .arrow.left { left:-12px; }
    .arrow.right { right:-12px; }

    .tools-grid, .trust-grid, .reads-grid { display:grid; gap:.8rem; }
    .tools-grid { grid-template-columns: repeat(3, minmax(0,1fr)); }
    .tool { padding:1rem; }
    .tool h3 { font-size:1.05rem; margin-bottom:.35rem; }

    .tabs { display:flex; gap:.45rem; flex-wrap:wrap; margin-bottom:.85rem; }
    .tab {
      border:1px solid var(--line); background:#fff; color:var(--muted); border-radius:999px;
      padding:.45rem .8rem; cursor:pointer; font-weight:700; font-size:.85rem;
    }
    .tab.active { background: var(--primary); color:#fff; border-color:var(--primary); }
    .reads-grid { grid-template-columns: repeat(4, minmax(0,1fr)); }
    .read { padding:.9rem; }
    .read .cat { font-size:.75rem; text-transform:uppercase; color:var(--primary); font-weight:700; letter-spacing:.04em; }
    .read h3 { font-size:1.03rem; margin:.45rem 0 .35rem; }

    .newsletter {
      margin: 1.4rem 0;
      background: linear-gradient(135deg, #185f56 0%, #1f8a7b 70%);
      border-radius: calc(var(--radius) + 2px); color:#f7fffd; padding:1.25rem;
      display:grid; grid-template-columns: 1.1fr .9fr; gap:1rem; align-items:center;
      box-shadow: var(--shadow);
    }
    .newsletter p { color:#d3f3eb; }
    .signup { display:flex; gap:.55rem; }
    .signup input { flex:1; border:0; border-radius:10px; padding:.78rem .84rem; font:inherit; }
    .signup button { border:0; border-radius:10px; padding:.78rem .95rem; background:var(--accent); color:#fff; font-weight:800; cursor:pointer; }

    .trust-grid { grid-template-columns: repeat(4, minmax(0,1fr)); }
    .pillar { padding:1rem; }
    .pillar h3 { font-size:1.03rem; margin:.45rem 0 .3rem; }
    .icon { width:34px; height:34px; border-radius:10px; background:#e5f5f1; display:grid; place-items:center; color:var(--primary-dark); font-weight:800; }

    footer { padding:1.7rem 0 2.4rem; color:var(--muted); font-size:.9rem; }

    @media (max-width: 1024px){
      .hero-grid { grid-template-columns: 1fr; }
      .tools-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .reads-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .trust-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .mega.open { grid-template-columns: repeat(2, minmax(0,1fr)); }
    }
    @media (max-width: 700px){
      .container { width: min(var(--container), calc(100% - 1.2rem)); }
      .topbar-wrap { align-items:flex-start; flex-direction:column; padding: .6rem 0; }
      .menu { gap:.15rem; }
      .tools-grid, .reads-grid, .trust-grid, .mega.open, .newsletter { grid-template-columns: 1fr; }
      .signup { flex-direction:column; }
      .arrow { display:none; }
      .topic { min-width: 145px; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="container topbar-wrap">
      <a class="brand" href="index.html"><span class="brand-dot"></span>WellSource</a>
      <nav class="main-nav" aria-label="Main navigation">
        <ul class="menu" id="main-menu">
          <li><button class="menu-btn" data-menu="conditions">Health Conditions</button></li>
          <li><button class="menu-btn" data-menu="wellness">Wellness</button></li>
          <li><button class="menu-btn" data-menu="tools">Tools</button></li>
          <li><button class="menu-btn" data-menu="featured">Featured</button></li>
          <li><button class="menu-btn" data-menu="connect">Connect</button></li>
        </ul>
        <div id="mega" class="mega" role="region" aria-live="polite"></div>
      </nav>
    </div>
    <div class="ticker" aria-label="Credibility stats ticker">
      <div class="ticker-track" id="tickerTrack"></div>
    </div>
  </header>

  <main>
    <section class="hero container">
      <div class="hero-grid">
        <article class="card hero-main">
          <div class="meta">
            <span class="pill">Medically Reviewed</span>
            <span class="pill">Updated April 2026</span>
          </div>
          <h1>Your trusted source for everyday health answers.</h1>
          <p>WellSource brings practical, expert-backed guidance to help you make confident decisions for your body and mind — from daily wellness to chronic condition support.</p>
          <button class="cta">Explore top guides →</button>
        </article>
        <aside class="card trending" aria-label="Trending articles">
          <h3>Trending Articles</h3>
          <div id="trendingList"></div>
        </aside>
      </div>
    </section>

    <section class="section container">
      <div class="section-head"><h2>Browse Health Topics</h2><p>Find trusted guidance by condition or wellness area.</p></div>
      <div class="carousel-wrap">
        <button class="arrow left" id="topicPrev" aria-label="Scroll topics left">←</button>
        <div class="carousel" id="topicsCarousel"></div>
        <button class="arrow right" id="topicNext" aria-label="Scroll topics right">→</button>
      </div>
    </section>

    <section class="section container">
      <div class="section-head"><h2>Health Tools</h2><p>Practical tools and calculators for daily health decisions.</p></div>
      <div class="tools-grid" id="toolsGrid"></div>
    </section>

    <section class="section container">
      <div class="section-head"><h2>Recommended Reads</h2><p>Curated picks by category, updated weekly.</p></div>
      <div class="tabs" id="tabs"></div>
      <div class="reads-grid" id="readsGrid"></div>
    </section>

    <section class="container">
      <div class="newsletter">
        <div>
          <h2>Get trusted health insights in your inbox</h2>
          <p>Join our newsletter for evidence-based tips, new tools, and expert-backed stories — no spam, just useful guidance.</p>
        </div>
        <form class="signup" id="newsletterForm">
          <input type="email" id="email" placeholder="Enter your email address" required aria-label="Email address" />
          <button type="submit">Join Now</button>
        </form>
      </div>
    </section>

    <section class="section container">
      <div class="section-head"><h2>Why readers trust WellSource</h2><p>Our editorial standards are built for clarity, safety, and action.</p></div>
      <div class="trust-grid" id="trustGrid"></div>
    </section>
  </main>

  <footer class="container">© 2026 WellSource Media. Evidence-led health content for everyday life.</footer>

  <script>
    const data = {
      credibilityStats: [
        "Medically reviewed content",
        "145 medical reviewers in network",
        "21 years of experience",
        "55 million monthly readers"
      ],
      megaMenu: {
        conditions: {
          title: "Health Conditions",
          columns: {
            "Popular": ["Anxiety & Depression","Type 2 Diabetes","Heart Health","Digestive Health"],
            "Women’s Health": ["Menopause","Hormonal Health","Pregnancy"],
            "Chronic Care": ["Arthritis","Thyroid","High Blood Pressure"],
            "Learn": ["Symptoms Checker","Condition Guides","Expert Q&A"]
          }
        },
        wellness: {
          title: "Wellness",
          columns: {
            "Mind": ["Stress Relief","Sleep","Mental Well-Being"],
            "Body": ["Fitness","Mobility","Weight Management"],
            "Food": ["Recipes","Nutrition Basics","Meal Plans"],
            "Lifestyle": ["Healthy Habits","Aging Well","Productivity"]
          }
        },
        tools: {
          title: "Tools",
          columns: {
            "Calculators": ["Macronutrient Calculator","Calorie Calculator","BMI Tool"],
            "Medication": ["Drug Directory: A to Z","Pill Identifier","Interaction Checker"],
            "Care": ["FindCare","Doctor Prep Checklist","Visit Planner"],
            "Tracking": ["Symptom Tracker","Habit Tracker","Hydration Log"]
          }
        },
        featured: {
          title: "Featured",
          columns: {
            "This Week": ["Editor’s Picks","Top Reads","Must-Know Updates"],
            "Series": ["Healthy Home","Move Better","Eat Smarter"],
            "Reviews": ["Product Reviews","Best Apps","Wearables"],
            "Voices": ["Patient Stories","Expert Roundtables","Community"]
          }
        },
        connect: {
          title: "Connect",
          columns: {
            "Follow": ["Instagram","YouTube","Podcast"],
            "Community": ["Discussion Groups","Challenges","Events"],
            "Newsletter": ["Daily Brief","Weekly Roundup","Condition Updates"],
            "Support": ["Contact Us","Partner With Us","Press"]
          }
        }
      },
      trending: [
        ["Heart Health","How to Make a Heart-Healthy Grocery List"],
        ["Wellness","The Worst U.S Cities for Spring Allergies in 2026, Ranked"],
        ["Lifestyle","Can You Run a Marathon ... with POTS?"],
        ["Products","Is Floor Sitting the New Standing? This Unique Desk Surprised Us"]
      ],
      topics: [
        "Anxiety & Depression","Digestive Health","Heart Health","Menopause","Type 2 Diabetes","Weight Management",
        "Sleep Health","Skin Care","Nutrition","Chronic Pain"
      ],
      tools: [
        ["Recipe Hub","Personalized, easy meals for your health goals."],
        ["Macronutrient Calculator","Estimate your protein, carbs, and fat targets."],
        ["Calorie Calculator","Understand your daily energy needs in minutes."],
        ["Drug Directory: A to Z","Search medication details and safety notes."],
        ["Pill Identifier","Identify pills by color, shape, and imprint."],
        ["FindCare","Locate doctors and specialists near you."]
      ],
      tabs: ["Top Reads","Fitness","Mental Well-Being","Product Reviews","Recipes","Skin Care"],
      reads: {
        "Top Reads": [
          ["Nutrition","16 Superfoods That Are Worthy of the Title"],
          ["Medication","Does Ozempic Cause Hair Loss?"],
          ["Mental Well-Being","Can Music Therapy Help with Depression?"],
          ["Products","These Are the 8 Best Calorie Counter Apps"]
        ],
        "Fitness": [
          ["Training","How to Build a Sustainable Walking Routine"],
          ["Mobility","Stretching Myths Physical Therapists Want You to Ignore"],
          ["Cardio","Zone 2 Training: Why Everyone Talks About It"],
          ["Recovery","Post-Workout Meals That Actually Help Recovery"]
        ],
        "Mental Well-Being": [
          ["Stress","5-Minute Resets for Busy Workdays"],
          ["Mood","How Sleep Debt Affects Your Emotions"],
          ["Mindfulness","Simple Breathing Drills for Anxiety Spikes"],
          ["Support","When to Talk to a Therapist — and How to Start"]
        ],
        "Product Reviews": [
          ["Wearables","Best Smart Rings for Sleep Tracking"],
          ["Home Fitness","Compact Desks That Support Better Posture"],
          ["Nutrition","Top Blenders for Daily Smoothies"],
          ["Tech","Do Blue-Light Glasses Actually Work?"]
        ],
        "Recipes": [
          ["Meal Prep","High-Protein Lunches Under 20 Minutes"],
          ["Heart Health","Low-Sodium Dinners with Big Flavor"],
          ["Digestive Health","Gut-Friendly Breakfast Bowls"],
          ["Budget","Healthy Grocery Staples for Busy Weeks"]
        ],
        "Skin Care": [
          ["Dermatology","Retinol Basics: Start Without Irritation"],
          ["Sun Safety","How Much Sunscreen Do You Really Need?"],
          ["Routine","Simple PM Skin Routine for Sensitive Skin"],
          ["Products","Fragrance-Free Moisturizers Dermatologists Like"]
        ]
      },
      trustPillars: [
        ["For you, by experts","Our stories are produced by health journalists and clinicians who understand real-life decisions."],
        ["Built to move you forward","Every guide offers practical next steps you can use today."],
        ["Reviewed by professionals","Licensed medical reviewers fact-check each clinically sensitive article."],
        ["Always up to date","We regularly audit and refresh content as guidelines evolve."]
      ]
    };

    const tickerTrack = document.getElementById('tickerTrack');
    const tickerItems = [...data.credibilityStats, ...data.credibilityStats];
    tickerTrack.innerHTML = tickerItems.map(s => `<span class="stat"><span class="dot"></span><b>${s.split(' ')[0]}</b> ${s.slice(s.indexOf(' ') + 1)}</span>`).join('');

    const trendingList = document.getElementById('trendingList');
    trendingList.innerHTML = data.trending.map(([cat, title]) => `<article class="trend-item"><div class="trend-cat">${cat}</div><a href="#">${title}</a></article>`).join('');

    const topicsCarousel = document.getElementById('topicsCarousel');
    topicsCarousel.innerHTML = data.topics.map(topic => `<article class="topic"><div class="topic-img"></div><span>${topic}</span></article>`).join('');
    document.getElementById('topicPrev').addEventListener('click', () => topicsCarousel.scrollBy({left: -260, behavior: 'smooth'}));
    document.getElementById('topicNext').addEventListener('click', () => topicsCarousel.scrollBy({left: 260, behavior: 'smooth'}));

    const toolsGrid = document.getElementById('toolsGrid');
    toolsGrid.innerHTML = data.tools.map(([name, desc]) => `<article class="card tool"><h3>${name}</h3><p>${desc}</p></article>`).join('');

    const tabs = document.getElementById('tabs');
    const readsGrid = document.getElementById('readsGrid');
    function renderReads(tabName){
      readsGrid.innerHTML = data.reads[tabName].map(([cat, title]) => `<article class="card read"><div class="cat">${cat}</div><h3>${title}</h3><p>Evidence-informed insights reviewed by our editorial team.</p></article>`).join('');
      [...tabs.querySelectorAll('.tab')].forEach(btn => btn.classList.toggle('active', btn.dataset.tab === tabName));
    }
    tabs.innerHTML = data.tabs.map((t, i) => `<button class="tab ${i===0?'active':''}" data-tab="${t}">${t}</button>`).join('');
    tabs.addEventListener('click', (e) => {
      const btn = e.target.closest('.tab');
      if(!btn) return;
      renderReads(btn.dataset.tab);
    });
    renderReads('Top Reads');

    const trustGrid = document.getElementById('trustGrid');
    trustGrid.innerHTML = data.trustPillars.map(([title, desc], i) => `<article class="card pillar"><div class="icon">${i+1}</div><h3>${title}</h3><p>${desc}</p></article>`).join('');

    const mega = document.getElementById('mega');
    const menuButtons = [...document.querySelectorAll('.menu-btn')];
    function openMega(key){
      const entry = data.megaMenu[key];
      if(!entry) return;
      mega.innerHTML = Object.entries(entry.columns).map(([heading, links]) => `
        <div class="mega-col"><h4>${heading}</h4>${links.map(l=>`<a href="#">${l}</a>`).join('')}</div>
      `).join('');
      mega.classList.add('open');
      menuButtons.forEach(btn => btn.classList.toggle('active', btn.dataset.menu === key));
    }
    menuButtons.forEach(btn => btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const isActive = btn.classList.contains('active') && mega.classList.contains('open');
      if(isActive){ mega.classList.remove('open'); btn.classList.remove('active'); return; }
      openMega(btn.dataset.menu);
    }));
    document.addEventListener('click', (e) => {
      if(!e.target.closest('.main-nav')){
        mega.classList.remove('open');
        menuButtons.forEach(btn => btn.classList.remove('active'));
      }
    });

    document.getElementById('newsletterForm').addEventListener('submit', (e) => {
      e.preventDefault();
      const email = document.getElementById('email');
      if(!email.checkValidity()) return;
      alert(`Thanks for joining WellSource, ${email.value}!`);
      e.target.reset();
    });
  </script>
</body>
</html>
